import React from 'react';
import {
  AppBar,
  Toolbar,
  Typography,
  Box,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  SelectChangeEvent,
  Avatar,
  Chip
} from '@mui/material';
import SmartToyRoundedIcon from '@mui/icons-material/SmartToyRounded';
import { CustomModel } from '../types';

interface AppHeaderProps {
  purposes: string[];
  purpose: string;
  onPurposeChange: (event: SelectChangeEvent<string>) => void;
  customModels: CustomModel[];
  selectedModelId: string | null;
  onModelSelect: (event: SelectChangeEvent<string>) => void;
}

const AppHeader: React.FC<AppHeaderProps> = ({
  purposes,
  purpose,
  onPurposeChange,
  customModels,
  selectedModelId,
  onModelSelect,
}) => {
  return (
    <AppBar 
      position="static" 
      elevation={0} 
      sx={{ 
        borderBottom: '1px solid rgba(80, 100, 240, 0.3)',
        background: 'rgba(10, 15, 30, 0.8)',
        backdropFilter: 'blur(10px)',
        boxShadow: '0 4px 20px rgba(0, 0, 0, 0.2)'
      }}
    >
      <Toolbar sx={{ display: 'flex', alignItems: 'center', gap: 2, py: 1.5 }}>
        <Box sx={{ display: 'flex', alignItems: 'center' }}>
          <Avatar
            sx={{
              background: 'linear-gradient(135deg, #4776E6 0%, #8E54E9 100%)',
              width: 42,
              height: 42,
              mr: 1.5,
              boxShadow: '0 0 15px rgba(71, 118, 230, 0.4)',
              border: '2px solid rgba(80, 120, 255, 0.3)',
              '&:hover': {
                boxShadow: '0 0 20px rgba(71, 118, 230, 0.6)',
                transform: 'scale(1.05)',
                transition: 'all 0.3s ease-in-out'
              }
            }}
          >
            <SmartToyRoundedIcon sx={{ color: 'white' }} />
          </Avatar>
          <Typography 
            variant="h5" 
            sx={{ 
              fontWeight: 700, 
              background: 'linear-gradient(45deg, #4776E6 30%, #8E54E9 90%)',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
              textShadow: '0 0 20px rgba(71, 118, 230, 0.3)',
              letterSpacing: '0.5px'
            }}
          >
            AI Chatbot
          </Typography>
        </Box>
        
        <FormControl 
          size="small" 
          sx={{ 
            minWidth: 220, 
            ml: 'auto',
            '& .MuiOutlinedInput-root': {
              borderRadius: '12px',
              bgcolor: 'rgba(15, 23, 42, 0.6)',
              border: '1px solid rgba(80, 120, 255, 0.3)',
              backdropFilter: 'blur(8px)',
              transition: 'all 0.2s ease',
              '& .MuiOutlinedInput-notchedOutline': {
                borderColor: 'rgba(80, 120, 255, 0.3)',
              },
              '&:hover': {
                bgcolor: 'rgba(15, 23, 42, 0.7)',
                '& .MuiOutlinedInput-notchedOutline': {
                  borderColor: 'rgba(80, 120, 255, 0.5)',
                },
              },
              '&.Mui-focused': {
                bgcolor: 'rgba(15, 23, 42, 0.8)',
                boxShadow: '0 0 10px rgba(80, 120, 255, 0.3)',
                '& .MuiOutlinedInput-notchedOutline': {
                  borderColor: 'rgba(80, 120, 255, 0.7)',
                  borderWidth: '1px',
                },
              }
            },
            '& .MuiInputLabel-root': {
              color: 'rgba(255, 255, 255, 0.7)',
              '&.Mui-focused': {
                color: '#8E54E9',
              }
            },
            '& .MuiSelect-select': {
              color: 'white',
            },
            '& .MuiSvgIcon-root': {
              color: 'rgba(255, 255, 255, 0.7)',
            }
          }}
        >
          <InputLabel id="chat-type-label">Chat Type</InputLabel>
          <Select
            labelId="chat-type-label"
            value={selectedModelId || purpose}
            label="Chat Type"
            onChange={(e) => {
              const value = e.target.value;
              if (customModels.some(model => model.id === value)) {
                onModelSelect(e);
              } else {
                onPurposeChange(e);
              }
            }}
            MenuProps={{
              PaperProps: {
                elevation: 3,
                sx: {
                  mt: 1,
                  borderRadius: 2,
                  bgcolor: 'rgba(10, 15, 30, 0.95)',
                  backdropFilter: 'blur(10px)',
                  border: '1px solid rgba(80, 120, 255, 0.2)',
                  boxShadow: '0 10px 25px rgba(0, 0, 0, 0.3)',
                  maxHeight: 400,
                  '& .MuiMenuItem-root': {
                    color: 'rgba(255, 255, 255, 0.9)',
                    '&:hover': {
                      bgcolor: 'rgba(80, 120, 255, 0.15)',
                    },
                    '&.Mui-selected': {
                      bgcolor: 'rgba(80, 120, 255, 0.2)',
                      '&:hover': {
                        bgcolor: 'rgba(80, 120, 255, 0.25)',
                      }
                    }
                  }
                }
              }
            }}
            renderValue={(selected) => {
              const selectedModel = customModels.find(model => model.id === selected);
              if (selectedModel) {
                return (
                  <Chip
                    avatar={<SmartToyRoundedIcon fontSize="small" sx={{ color: 'white' }} />}
                    label={selectedModel.name}
                    size="small"
                    sx={{ 
                      height: 28, 
                      borderRadius: '8px',
                      background: 'linear-gradient(135deg, #4776E6 0%, #8E54E9 100%)',
                      color: 'white',
                      fontWeight: 500,
                      border: '1px solid rgba(255, 255, 255, 0.2)',
                      boxShadow: '0 2px 5px rgba(0, 0, 0, 0.1)',
                      '& .MuiChip-avatar': {
                        color: 'white',
                      }
                    }}
                  />
                );
              }
              return <span style={{ color: 'white' }}>{selected}</span>;
            }}
          >
            <Typography 
              variant="subtitle2" 
              sx={{ 
                px: 2, 
                py: 1, 
                color: 'rgba(255, 255, 255, 0.7)', 
                fontWeight: 600,
                borderBottom: '1px solid rgba(80, 120, 255, 0.2)'
              }}
            >
              General Chat
            </Typography>
            {purposes.map((p) => (
              <MenuItem key={p} value={p} sx={{ py: 1.5 }}>
                {p}
              </MenuItem>
            ))}
            
            {customModels.length > 0 && (
              <>
                <Typography 
                  variant="subtitle2" 
                  sx={{ 
                    px: 2, 
                    py: 1, 
                    mt: 1, 
                    color: 'rgba(255, 255, 255, 0.7)', 
                    fontWeight: 600,
                    borderBottom: '1px solid rgba(80, 120, 255, 0.2)'
                  }}
                >
                  My Custom Models
                </Typography>
                {customModels.map((model) => (
                  <MenuItem key={model.id} value={model.id} sx={{ py: 1.5 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                      <Avatar
                        sx={{
                          width: 24,
                          height: 24,
                          mr: 1,
                          background: 'linear-gradient(135deg, #4776E6 0%, #8E54E9 100%)',
                          fontSize: '0.75rem'
                        }}
                      >
                        <SmartToyRoundedIcon fontSize="small" sx={{ fontSize: '1rem' }} />
                      </Avatar>
                      {model.name}
                    </Box>
                  </MenuItem>
                ))}
              </>
            )}
          </Select>
        </FormControl>
      </Toolbar>
    </AppBar>
  );
};

export default AppHeader; 