import React, { useState, useEffect, useRef } from 'react';
import { 
  Box, 
  IconButton, 
  Text,
  Spinner,
  useToast,
  Tooltip
} from '@chakra-ui/react';
import { keyframes } from '@emotion/react';
import { FaMicrophone, FaStop } from 'react-icons/fa';
import { API_BASE_URL } from '../constants';
import IconWrapper from './IconWrapper';

interface VoiceInputProps {
  onTranscript: (text: string) => void;
  isDisabled?: boolean;
}

// Definer nye keyframes for pulserende animasjon
const pulseKeyframes = keyframes`
  0% { transform: scale(1); box-shadow: 0 0 0 0 rgba(80, 100, 240, 0.5); }
  70% { transform: scale(1.05); box-shadow: 0 0 0 10px rgba(80, 100, 240, 0); }
  100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(80, 100, 240, 0); }
`;

// Definer nye keyframes for audio wave animasjon
const audioWaveKeyframes = keyframes`
  0% { height: 3px; }
  50% { height: 15px; }
  100% { height: 3px; }
`;

const VoiceInput: React.FC<VoiceInputProps> = ({ 
  onTranscript,
  isDisabled = false
}) => {
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const toast = useToast();

  const pulseAnimation = `${pulseKeyframes} 2s infinite`;
  const audioWaveAnimation = (delay: number) => `${audioWaveKeyframes} 1.2s ease-in-out ${delay}s infinite`;

  useEffect(() => {
    return () => {
      // Clean up recording when component unmounts
      if (mediaRecorderRef.current && isRecording) {
        mediaRecorderRef.current.stop();
      }
    };
  }, [isRecording]);

  const startRecording = async () => {
    try {
      audioChunksRef.current = [];
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      
      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };
      
      mediaRecorder.onstop = async () => {
        setIsProcessing(true);
        try {
          // Convert audio chunks to audio file
          const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/mp3' });
          await processAudio(audioBlob);
        } catch (error) {
          console.error('Error processing audio:', error);
          toast({
            title: 'Feil ved behandling av lydopptak',
            description: 'Kunne ikke behandle stemmeopptaket ditt. Vennligst prøv igjen.',
            status: 'error',
            duration: 5000,
            isClosable: true,
            position: 'top',
            variant: 'solid',
          });
        }
        
        // Stop all tracks to release microphone
        stream.getTracks().forEach(track => track.stop());
        setIsProcessing(false);
      };
      
      mediaRecorderRef.current = mediaRecorder;
      mediaRecorder.start();
      setIsRecording(true);
      
      toast({
        title: 'Opptak startet',
        description: 'Si det du vil spørre om',
        status: 'info',
        duration: 3000,
        isClosable: true,
        position: 'top',
        variant: 'solid',
        containerStyle: {
          background: 'rgba(15, 23, 42, 0.8)',
          backdropFilter: 'blur(8px)',
          borderRadius: '12px',
          border: '1px solid rgba(80, 100, 240, 0.3)',
        }
      });
    } catch (error) {
      console.error('Error starting recording:', error);
      toast({
        title: 'Kunne ikke starte opptak',
        description: 'Vennligst gi nettleseren tilgang til mikrofonen din.',
        status: 'error',
        duration: 5000,
        isClosable: true,
        position: 'top',
        variant: 'solid',
      });
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const processAudio = async (audioBlob: Blob) => {
    const formData = new FormData();
    formData.append('file', audioBlob, 'recording.mp3');
    
    try {
      const response = await fetch(`${API_BASE_URL}/api/transcribe`, {
        method: 'POST',
        body: formData,
      });
      
      if (!response.ok) {
        throw new Error(`Server returned ${response.status}: ${response.statusText}`);
      }
      
      const data = await response.json();
      if (data.text) {
        onTranscript(data.text);
        
        toast({
          title: 'Transkripsjon fullført',
          description: 'Din stemme har blitt konvertert til tekst.',
          status: 'success',
          duration: 3000,
          isClosable: true,
          position: 'top',
          variant: 'solid',
        });
      }
    } catch (error) {
      console.error('Error transcribing audio:', error);
      toast({
        title: 'Transkripsjonsfeil',
        description: 'Kunne ikke konvertere stemmen din til tekst. Vennligst prøv igjen.',
        status: 'error',
        duration: 5000,
        isClosable: true,
        position: 'top',
        variant: 'solid',
      });
    }
  };

  return (
    <Box>
      {isRecording && (
        <Box 
          display="flex" 
          justifyContent="center" 
          alignItems="center" 
          mb={4}
          gap={1}
        >
          {[0, 1, 2, 3, 4].map((i) => (
            <Box
              key={i}
              width="4px"
              height="3px"
              backgroundColor="blue.400"
              borderRadius="full"
              animation={audioWaveAnimation(i * 0.1)}
              mx="1px"
            />
          ))}
        </Box>
      )}
      
      <Tooltip label={isRecording ? "Stopp opptak" : "Start talegjenkjenning"}>
        <IconButton
          aria-label={isRecording ? "Stopp opptak" : "Start talegjenkjenning"}
          icon={isProcessing ? <Spinner size="sm" color="white" /> : (
            isRecording ? <IconWrapper icon={FaStop} boxSize="18px" /> : <IconWrapper icon={FaMicrophone} boxSize="20px" />
          )}
          onClick={isRecording ? stopRecording : startRecording}
          colorScheme={isRecording ? "red" : "blue"}
          isRound
          size="lg"
          isDisabled={isDisabled || isProcessing}
          animation={isRecording ? pulseAnimation : undefined}
          boxShadow={isRecording ? "0 0 15px rgba(255, 60, 60, 0.6)" : "0 0 10px rgba(80, 120, 255, 0.5)"}
          bg={isRecording ? "linear-gradient(45deg, #FF3C3C 0%, #FF5C5C 100%)" : "linear-gradient(45deg, #4776E6 0%, #8E54E9 100%)"}
          _hover={{
            bg: isRecording 
              ? "linear-gradient(45deg, #FF3C3C 30%, #FF5C5C 100%)" 
              : "linear-gradient(45deg, #4776E6 30%, #8E54E9 90%)",
            transform: "translateY(-2px)",
            boxShadow: isRecording 
              ? "0 0 20px rgba(255, 60, 60, 0.7)" 
              : "0 0 15px rgba(80, 120, 255, 0.6)"
          }}
          _active={{
            transform: "translateY(0)",
          }}
          transition="all 0.2s ease-in-out"
        />
      </Tooltip>
      {isRecording && (
        <Text 
          fontSize="sm" 
          color="blue.200" 
          mt={3}
          textAlign="center"
          fontWeight="medium"
          letterSpacing="0.5px"
        >
          Opptak pågår...
        </Text>
      )}
    </Box>
  );
};

export default VoiceInput; 