import React from 'react';
import { Box, Paper, Typography, CircularProgress, Avatar, Fade } from '@mui/material';
import { PersonRounded, SmartToyRounded } from '@mui/icons-material';
import { Message } from '../types'; // Import the Message type
import { format } from 'date-fns'; // Import date formatting library

interface ChatMessageListProps {
  messages: Message[];
  loading: boolean;
  messagesEndRef: React.RefObject<HTMLDivElement>;
}

const ChatMessageList: React.FC<ChatMessageListProps> = ({ messages, loading, messagesEndRef }) => {
  return (
    <Box 
      sx={{ 
        flexGrow: 1, 
        overflowY: 'auto', 
        p: { xs: 2, sm: 3 }, 
        bgcolor: 'transparent',
        backgroundImage: 'radial-gradient(rgba(80, 120, 255, 0.15) 1px, transparent 1px)',
        backgroundSize: '25px 25px',
        '&::-webkit-scrollbar': {
          width: '8px',
          backgroundColor: 'rgba(0, 0, 0, 0.1)',
        },
        '&::-webkit-scrollbar-thumb': {
          backgroundColor: 'rgba(80, 120, 255, 0.3)',
          borderRadius: '4px',
          '&:hover': {
            backgroundColor: 'rgba(80, 120, 255, 0.5)',
          }
        }
      }}
    >
      {messages.length === 0 && (
        <Box sx={{ 
          height: '100%', 
          display: 'flex', 
          flexDirection: 'column', 
          justifyContent: 'center', 
          alignItems: 'center',
          opacity: 0.9
        }}>
          <Box
            sx={{
              height: 100,
              width: 100,
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              background: 'linear-gradient(45deg, rgba(70, 118, 230, 0.2) 0%, rgba(142, 84, 233, 0.2) 100%)',
              backdropFilter: 'blur(8px)',
              border: '1px solid rgba(80, 120, 255, 0.3)',
              boxShadow: '0 0 30px rgba(80, 120, 255, 0.2)',
              mb: 3
            }}
          >
            <SmartToyRounded 
              fontSize="large" 
              sx={{ 
                fontSize: 50, 
                color: '#8E54E9',
                filter: 'drop-shadow(0 0 10px rgba(142, 84, 233, 0.5))'
              }} 
            />
          </Box>
          <Typography 
            variant="h5" 
            sx={{ 
              color: 'white', 
              fontWeight: 600, 
              letterSpacing: 1, 
              textShadow: '0 0 10px rgba(80, 120, 255, 0.5)',
              mb: 1
            }}
          >
            AI Chatbot
          </Typography>
          <Typography 
            variant="body1" 
            sx={{ 
              color: 'rgba(255, 255, 255, 0.7)', 
              textAlign: 'center',
              maxWidth: '300px'
            }}
          >
            Send en melding for å starte samtalen
          </Typography>
        </Box>
      )}

      {messages.map((msg, index) => {
        const formattedTime = msg.timestamp 
          ? format(new Date(msg.timestamp), 'p') // Format to time like '1:30 PM'
          : '';
          
        const isUser = msg.role === 'user';
        const isFirstMessageOfGroup = index === 0 || messages[index - 1].role !== msg.role;
        const isLastMessageOfGroup = index === messages.length - 1 || messages[index + 1].role !== msg.role;
        
        // Dynamisk styling for meldingsboblene
        const userGradient = 'linear-gradient(135deg, #4776E6 0%, #8E54E9 100%)';
        const botGradient = 'linear-gradient(135deg, rgba(15, 23, 42, 0.8) 0%, rgba(30, 41, 59, 0.8) 100%)';
        
        return (
          <Fade 
            key={index} 
            in={true} 
            timeout={400} 
            style={{ transitionDelay: `${index * 80}ms` }}
          >
            <Box 
              sx={{
                display: 'flex',
                justifyContent: isUser ? 'flex-end' : 'flex-start',
                mb: 2.5,
                alignItems: 'flex-start',
              }}
            >
              {!isUser && isFirstMessageOfGroup && (
                <Avatar 
                  sx={{ 
                    background: 'linear-gradient(135deg, #8E54E9 0%, #4776E6 100%)', 
                    mr: 1.5, 
                    width: 40, 
                    height: 40,
                    boxShadow: '0 0 15px rgba(142, 84, 233, 0.3)',
                    border: '2px solid rgba(142, 84, 233, 0.3)'
                  }}
                >
                  <SmartToyRounded fontSize="small" sx={{ color: 'white' }} />
                </Avatar>
              )}
              
              {!isUser && !isFirstMessageOfGroup && <Box sx={{ width: 40, mr: 1.5 }} />}
              
              <Box 
                sx={{ 
                  display: 'flex', 
                  flexDirection: 'column', 
                  alignItems: isUser ? 'flex-end' : 'flex-start',
                  maxWidth: { xs: '80%', sm: '70%' }
                }}
              >
                <Paper
                  elevation={0}
                  sx={{
                    p: 2,
                    px: 2.5,
                    background: isUser ? userGradient : botGradient,
                    color: isUser ? 'white' : 'white',
                    wordWrap: 'break-word',
                    borderRadius: isUser
                      ? isFirstMessageOfGroup 
                        ? '20px 20px 4px 20px'
                        : isLastMessageOfGroup
                        ? '20px 4px 20px 20px'
                        : '20px 4px 4px 20px'
                      : isFirstMessageOfGroup
                        ? '4px 20px 20px 20px'
                        : isLastMessageOfGroup
                        ? '20px 20px 20px 4px'
                        : '4px 20px 20px 4px',
                    boxShadow: isUser 
                      ? '0 5px 15px rgba(71, 118, 230, 0.2)' 
                      : '0 5px 15px rgba(0, 0, 0, 0.1)',
                    backdropFilter: 'blur(8px)',
                    border: isUser 
                      ? '1px solid rgba(71, 118, 230, 0.3)'
                      : '1px solid rgba(255, 255, 255, 0.1)',
                    borderTopRightRadius: isUser && !isFirstMessageOfGroup ? 4 : undefined,
                    borderTopLeftRadius: !isUser && !isFirstMessageOfGroup ? 4 : undefined,
                    borderBottomRightRadius: isUser && !isLastMessageOfGroup ? 4 : undefined,
                    borderBottomLeftRadius: !isUser && !isLastMessageOfGroup ? 4 : undefined,
                    transition: 'all 0.2s ease-in-out',
                    '&:hover': {
                      boxShadow: isUser 
                        ? '0 8px 20px rgba(71, 118, 230, 0.25)' 
                        : '0 8px 20px rgba(0, 0, 0, 0.15)',
                      transform: 'translateY(-2px)'
                    }
                  }}
                >
                  <Typography 
                    variant="body1" 
                    sx={{ 
                      whiteSpace: 'pre-wrap',
                      lineHeight: 1.5,
                      fontWeight: 400,
                      letterSpacing: 0.2
                    }}
                  >
                    {msg.content}
                  </Typography>
                </Paper>
                
                {isLastMessageOfGroup && formattedTime && (
                  <Typography 
                    variant="caption" 
                    sx={{ 
                      color: 'rgba(255, 255, 255, 0.6)', 
                      mt: 0.7, 
                      px: 0.5,
                      fontSize: '0.7rem',
                      fontWeight: 500
                    }}
                  >
                    {formattedTime}
                  </Typography>
                )}
              </Box>
              
              {isUser && isFirstMessageOfGroup && (
                <Avatar 
                  sx={{ 
                    background: 'linear-gradient(135deg, #4776E6 0%, #8E54E9 100%)', 
                    ml: 1.5, 
                    width: 40, 
                    height: 40,
                    boxShadow: '0 0 15px rgba(71, 118, 230, 0.3)',
                    border: '2px solid rgba(71, 118, 230, 0.3)'
                  }}
                >
                  <PersonRounded fontSize="small" sx={{ color: 'white' }} />
                </Avatar>
              )}
              
              {isUser && !isFirstMessageOfGroup && <Box sx={{ width: 40, ml: 1.5 }} />}
            </Box>
          </Fade>
        );
      })}

      {loading && (
        <Fade in={loading} timeout={300}>
          <Box 
            sx={{ 
              display: 'flex', 
              alignItems: 'center', 
              mt: 2, 
              mb: 2,
              background: 'linear-gradient(135deg, rgba(15, 23, 42, 0.7) 0%, rgba(30, 41, 59, 0.7) 100%)',
              p: 2,
              px: 3,
              borderRadius: '18px',
              width: 'fit-content',
              boxShadow: '0 5px 15px rgba(0, 0, 0, 0.1)',
              backdropFilter: 'blur(8px)',
              border: '1px solid rgba(255, 255, 255, 0.1)',
            }}
          >
            <CircularProgress 
              size={18} 
              thickness={5} 
              sx={{ 
                mr: 2, 
                color: '#8E54E9'
              }} 
            />
            <Typography 
              variant="body2" 
              sx={{ 
                color: 'rgba(255, 255, 255, 0.9)',
                fontWeight: 500,
                letterSpacing: 0.5
              }}
            >
              Tenker...
            </Typography>
          </Box>
        </Fade>
      )}
      
      <div ref={messagesEndRef} />
    </Box>
  );
};

export default ChatMessageList; 